macro_rules! deps {
    () => {
        Encoding!();
        VariantEncoder!();
        Unicode!();
    };
}

macro_rules! Encoder {
    () => {
        deps!();
        # [doc = " A converter that encodes a Unicode stream into bytes according to a"] # [doc = " character encoding in a streaming (incremental) manner."] # [doc = ""] # [doc = " The various `encode_*` methods take an input buffer (`src`) and an output"] # [doc = " buffer `dst` both of which are caller-allocated. There are variants for"] # [doc = " both UTF-8 and UTF-16 input buffers."] # [doc = ""] # [doc = " An `encode_*` method encode characters from `src` into bytes characters"] # [doc = " stored into `dst` until one of the following three things happens:"] # [doc = ""] # [doc = " 1. An unmappable character is encountered (`*_without_replacement` variants"] # [doc = "    only)."] # [doc = ""] # [doc = " 2. The output buffer has been filled so near capacity that the decoder"] # [doc = "    cannot be sure that processing an additional character of input wouldn't"] # [doc = "    cause so much output that the output buffer would overflow."] # [doc = ""] # [doc = " 3. All the input characters have been processed."] # [doc = ""] # [doc = " The `encode_*` method then returns tuple of a status indicating which one"] # [doc = " of the three reasons to return happened, how many input code units (`u8`"] # [doc = " when encoding from UTF-8 and `u16` when encoding from UTF-16) were read,"] # [doc = " how many output bytes were written (except when encoding into `Vec<u8>`,"] # [doc = " whose length change indicates this), and in the case of the variants that"] # [doc = " perform replacement, a boolean indicating whether an unmappable"] # [doc = " character was replaced with a numeric character reference during the call."] # [doc = ""] # [doc = " The number of bytes \"written\" is what's logically written. Garbage may be"] # [doc = " written in the output buffer beyond the point logically written to."] # [doc = ""] # [doc = " In the case of the methods whose name ends with"] # [doc = " `*_without_replacement`, the status is an [`EncoderResult`][1] enumeration"] # [doc = " (possibilities `Unmappable`, `OutputFull` and `InputEmpty` corresponding to"] # [doc = " the three cases listed above)."] # [doc = ""] # [doc = " In the case of methods whose name does not end with"] # [doc = " `*_without_replacement`, unmappable characters are automatically replaced"] # [doc = " with the corresponding numeric character references and unmappable"] # [doc = " characters do not cause the methods to return early."] # [doc = ""] # [doc = " When encoding from UTF-8 without replacement, the methods are guaranteed"] # [doc = " not to return indicating that more output space is needed if the length"] # [doc = " of the output buffer is at least the length returned by"] # [doc = " [`max_buffer_length_from_utf8_without_replacement()`][2]. When encoding from"] # [doc = " UTF-8 with replacement, the length of the output buffer that guarantees the"] # [doc = " methods not to return indicating that more output space is needed in the"] # [doc = " absence of unmappable characters is given by"] # [doc = " [`max_buffer_length_from_utf8_if_no_unmappables()`][3]. When encoding from"] # [doc = " UTF-16 without replacement, the methods are guaranteed not to return"] # [doc = " indicating that more output space is needed if the length of the output"] # [doc = " buffer is at least the length returned by"] # [doc = " [`max_buffer_length_from_utf16_without_replacement()`][4]. When encoding"] # [doc = " from UTF-16 with replacement, the the length of the output buffer that"] # [doc = " guarantees the methods not to return indicating that more output space is"] # [doc = " needed in the absence of unmappable characters is given by"] # [doc = " [`max_buffer_length_from_utf16_if_no_unmappables()`][5]."] # [doc = " When encoding with replacement, applications are not expected to size the"] # [doc = " buffer for the worst case ahead of time but to resize the buffer if there"] # [doc = " are unmappable characters. This is why max length queries are only available"] # [doc = " for the case where there are no unmappable characters."] # [doc = ""] # [doc = " When encoding from UTF-8, each `src` buffer _must_ be valid UTF-8. (When"] # [doc = " calling from Rust, the type system takes care of this.) When encoding from"] # [doc = " UTF-16, unpaired surrogates in the input are treated as U+FFFD REPLACEMENT"] # [doc = " CHARACTERS. Therefore, in order for astral characters not to turn into a"] # [doc = " pair of REPLACEMENT CHARACTERS, the caller must ensure that surrogate pairs"] # [doc = " are not split across input buffer boundaries."] # [doc = ""] # [doc = " After an `encode_*` call returns, the output produced so far, taken as a"] # [doc = " whole from the start of the stream, is guaranteed to consist of a valid"] # [doc = " byte sequence in the target encoding. (I.e. the code unit sequence for a"] # [doc = " character is guaranteed not to be split across output buffers. However, due"] # [doc = " to the stateful nature of ISO-2022-JP, the stream needs to be considered"] # [doc = " from the start for it to be valid. For other encodings, the validity holds"] # [doc = " on a per-output buffer basis.)"] # [doc = ""] # [doc = " The boolean argument `last` indicates that the end of the stream is reached"] # [doc = " when all the characters in `src` have been consumed. This argument is needed"] # [doc = " for ISO-2022-JP and is ignored for other encodings."] # [doc = ""] # [doc = " An `Encoder` object can be used to incrementally encode a byte stream."] # [doc = ""] # [doc = " During the processing of a single stream, the caller must call `encode_*`"] # [doc = " zero or more times with `last` set to `false` and then call `encode_*` at"] # [doc = " least once with `last` set to `true`. If `encode_*` returns `InputEmpty`,"] # [doc = " the processing of the stream has ended. Otherwise, the caller must call"] # [doc = " `encode_*` again with `last` set to `true` (or treat an `Unmappable` result"] # [doc = " as a fatal error)."] # [doc = ""] # [doc = " Once the stream has ended, the `Encoder` object must not be used anymore."] # [doc = " That is, you need to create another one to process another stream."] # [doc = ""] # [doc = " When the encoder returns `OutputFull` or the encoder returns `Unmappable`"] # [doc = " and the caller does not wish to treat it as a fatal error, the input buffer"] # [doc = " `src` may not have been completely consumed. In that case, the caller must"] # [doc = " pass the unconsumed contents of `src` to `encode_*` again upon the next"] # [doc = " call."] # [doc = ""] # [doc = " [1]: enum.EncoderResult.html"] # [doc = " [2]: #method.max_buffer_length_from_utf8_without_replacement"] # [doc = " [3]: #method.max_buffer_length_from_utf8_if_no_unmappables"] # [doc = " [4]: #method.max_buffer_length_from_utf16_without_replacement"] # [doc = " [5]: #method.max_buffer_length_from_utf16_if_no_unmappables"] # [doc = ""] # [doc = " # Infinite loops"] # [doc = ""] # [doc = " When converting with a fixed-size output buffer whose size is too small to"] # [doc = " accommodate one character of output, an infinite loop ensues. When"] # [doc = " converting with a fixed-size output buffer, it generally makes sense to"] # [doc = " make the buffer fairly large (e.g. couple of kilobytes)."] pub struct Encoder { encoding : & 'static Encoding , variant : VariantEncoder , }
    };
}

Encoder!()